package org.familysearch.tree.memories

interface MemoriesRepository {
    fun memories(personId: String): List<Memory>
}

package org.familysearch.tree.memories

class MemoriesViewModel(private val repo: MemoriesRepository) {
    private var cache: Map<String, List<Memory>> = emptyMap()

    fun load(personId: String): List<Memory> =
        cache[personId] ?: repo.memories(personId).also { cache = cache + (personId to it) }

    fun signedOut() {
        cache = emptyMap()
    }
}
